PRAGMA foreign_keys=ON;
CREATE TABLE schools(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL);
CREATE TABLE majors(id INTEGER PRIMARY KEY,school_id INTEGER NOT NULL REFERENCES schools(id),code TEXT NOT NULL UNIQUE,name TEXT NOT NULL);
CREATE TABLE users(id INTEGER PRIMARY KEY,login_no TEXT NOT NULL UNIQUE,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('REGISTRAR','SCHOOL_ADMIN','TEACHER','COUNSELOR','STUDENT')),school_id INTEGER REFERENCES schools(id),active INTEGER NOT NULL CHECK(active IN(0,1)));
CREATE TABLE classes(id INTEGER PRIMARY KEY,major_id INTEGER NOT NULL REFERENCES majors(id),name TEXT NOT NULL UNIQUE,admission_year INTEGER NOT NULL CHECK(admission_year BETWEEN 2020 AND 2030));
CREATE TABLE teachers(id INTEGER PRIMARY KEY REFERENCES users(id),title TEXT NOT NULL);
CREATE TABLE counselor_assignments(id INTEGER PRIMARY KEY,counselor_id INTEGER NOT NULL REFERENCES users(id),class_id INTEGER NOT NULL REFERENCES classes(id),valid_from TEXT NOT NULL,valid_to TEXT,CHECK(valid_to IS NULL OR valid_to>valid_from),UNIQUE(counselor_id,class_id,valid_from));
CREATE TABLE students(id INTEGER PRIMARY KEY REFERENCES users(id),student_no TEXT NOT NULL UNIQUE,class_id INTEGER NOT NULL REFERENCES classes(id),status TEXT NOT NULL CHECK(status IN('active','leave')));
CREATE TABLE student_contacts(student_id INTEGER PRIMARY KEY REFERENCES students(id),email TEXT NOT NULL UNIQUE,mobile TEXT NOT NULL,emergency_contact TEXT NOT NULL);
CREATE TABLE terms(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,start_date TEXT NOT NULL,end_date TEXT NOT NULL,enroll_from TEXT NOT NULL,add_drop_until TEXT NOT NULL,max_credits INTEGER NOT NULL CHECK(max_credits>0),CHECK(enroll_from<=start_date AND start_date<end_date AND add_drop_until BETWEEN start_date AND end_date));
CREATE TABLE calendar_days(term_id INTEGER NOT NULL REFERENCES terms(id),calendar_date TEXT NOT NULL,teaching_week INTEGER NOT NULL,teaching_weekday INTEGER NOT NULL CHECK(teaching_weekday BETWEEN 1 AND 7),is_teaching_day INTEGER NOT NULL CHECK(is_teaching_day IN(0,1)),note TEXT NOT NULL,PRIMARY KEY(term_id,calendar_date));
CREATE TABLE courses(id INTEGER PRIMARY KEY,school_id INTEGER NOT NULL REFERENCES schools(id),code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,credits INTEGER NOT NULL CHECK(credits BETWEEN 1 AND 6),kind TEXT NOT NULL CHECK(kind IN('required','elective')),room_type TEXT NOT NULL CHECK(room_type IN('lecture','computer_lab')));
CREATE TABLE prerequisites(course_id INTEGER NOT NULL REFERENCES courses(id),required_course_id INTEGER NOT NULL REFERENCES courses(id),PRIMARY KEY(course_id,required_course_id),CHECK(course_id<>required_course_id));
CREATE TABLE rooms(id INTEGER PRIMARY KEY,building TEXT NOT NULL,room_no TEXT NOT NULL,room_type TEXT NOT NULL CHECK(room_type IN('lecture','computer_lab')),capacity INTEGER NOT NULL CHECK(capacity>0),UNIQUE(building,room_no));
CREATE TABLE sections(id INTEGER PRIMARY KEY,term_id INTEGER NOT NULL REFERENCES terms(id),course_id INTEGER NOT NULL REFERENCES courses(id),section_no TEXT NOT NULL UNIQUE,capacity INTEGER NOT NULL CHECK(capacity>0),status TEXT NOT NULL CHECK(status IN('open','closed','cancelled')),audience_year INTEGER NOT NULL CHECK(audience_year BETWEEN 1 AND 4),version INTEGER NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE section_teachers(section_id INTEGER NOT NULL REFERENCES sections(id),teacher_id INTEGER NOT NULL REFERENCES teachers(id),is_lead INTEGER NOT NULL CHECK(is_lead IN(0,1)),PRIMARY KEY(section_id,teacher_id));
CREATE UNIQUE INDEX section_one_lead ON section_teachers(section_id) WHERE is_lead=1;
CREATE TABLE section_meetings(id INTEGER PRIMARY KEY,section_id INTEGER NOT NULL REFERENCES sections(id),room_id INTEGER NOT NULL REFERENCES rooms(id),weekday INTEGER NOT NULL CHECK(weekday BETWEEN 1 AND 7),period_from INTEGER NOT NULL,period_to INTEGER NOT NULL,week_from INTEGER NOT NULL,week_to INTEGER NOT NULL,CHECK(period_from BETWEEN 1 AND 12 AND period_to BETWEEN period_from AND 12),CHECK(week_from>=1 AND week_to BETWEEN week_from AND 20));
CREATE TABLE prior_credits(id INTEGER PRIMARY KEY,student_id INTEGER NOT NULL REFERENCES students(id),course_id INTEGER NOT NULL REFERENCES courses(id),score INTEGER NOT NULL CHECK(score BETWEEN 60 AND 100),recognized_on TEXT NOT NULL,source TEXT NOT NULL CHECK(source IN('historical_import','transfer')),UNIQUE(student_id,course_id));
CREATE TABLE enrollments(id INTEGER PRIMARY KEY,student_id INTEGER NOT NULL REFERENCES students(id),section_id INTEGER NOT NULL REFERENCES sections(id),status TEXT NOT NULL CHECK(status IN('enrolled','dropped','completed')),enrolled_on TEXT NOT NULL,dropped_on TEXT,CHECK((status='dropped' AND dropped_on>=enrolled_on) OR (status<>'dropped' AND dropped_on IS NULL)),UNIQUE(student_id,section_id));
CREATE TABLE assessments(id INTEGER PRIMARY KEY,section_id INTEGER NOT NULL REFERENCES sections(id),name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('coursework','midterm','final')),weight INTEGER NOT NULL CHECK(weight BETWEEN 1 AND 100),assessment_date TEXT NOT NULL,UNIQUE(section_id,kind));
CREATE TABLE grades(id INTEGER PRIMARY KEY,enrollment_id INTEGER NOT NULL REFERENCES enrollments(id),assessment_id INTEGER NOT NULL REFERENCES assessments(id),score INTEGER CHECK(score BETWEEN 0 AND 100),status TEXT NOT NULL CHECK(status IN('pending','graded','absent')),graded_by INTEGER REFERENCES teachers(id),graded_on TEXT,CHECK((status='pending' AND score IS NULL AND graded_by IS NULL AND graded_on IS NULL) OR (status IN('graded','absent') AND score IS NOT NULL AND graded_by IS NOT NULL AND graded_on IS NOT NULL)),CHECK(status<>'absent' OR score=0),UNIQUE(enrollment_id,assessment_id));
CREATE TABLE grade_releases(assessment_id INTEGER PRIMARY KEY REFERENCES assessments(id),released_by INTEGER NOT NULL REFERENCES teachers(id),released_at TEXT NOT NULL);
CREATE TABLE attendance(id INTEGER PRIMARY KEY,enrollment_id INTEGER NOT NULL REFERENCES enrollments(id),meeting_id INTEGER NOT NULL REFERENCES section_meetings(id),attendance_date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('present','late','excused','absent')),recorded_by INTEGER NOT NULL REFERENCES teachers(id),UNIQUE(enrollment_id,meeting_id,attendance_date));
CREATE TABLE exams(id INTEGER PRIMARY KEY,section_id INTEGER NOT NULL REFERENCES sections(id),room_id INTEGER NOT NULL REFERENCES rooms(id),exam_date TEXT NOT NULL,period_from INTEGER NOT NULL,period_to INTEGER NOT NULL,invigilator_id INTEGER NOT NULL REFERENCES teachers(id),CHECK(period_from>=1 AND period_to BETWEEN period_from AND 12),UNIQUE(section_id));
CREATE TABLE schema_comments(table_name TEXT NOT NULL,column_name TEXT NOT NULL,comment_zh TEXT NOT NULL,PRIMARY KEY(table_name,column_name));
CREATE INDEX students_class_idx ON students(class_id);
CREATE INDEX counselors_class_idx ON counselor_assignments(class_id,valid_from,valid_to);
CREATE INDEX teaching_teacher_idx ON section_teachers(teacher_id,section_id);
CREATE INDEX sections_term_idx ON sections(term_id,course_id);
CREATE INDEX meetings_section_idx ON section_meetings(section_id);
CREATE INDEX enrollments_student_idx ON enrollments(student_id,status);
CREATE INDEX enrollments_section_idx ON enrollments(section_id,status);
CREATE INDEX grades_assessment_idx ON grades(assessment_id,status);
CREATE INDEX attendance_enrollment_idx ON attendance(enrollment_id,attendance_date);
